import { Category, Post, RecommendedBlog, Tag, User } from "@/types/blog";

// 실제 Django 백엔드 (카테고리/태그/게시글)
const API_BASE_URL =
  process.env.NEXT_PUBLIC_API_BASE_URL ?? "http://localhost:5000/api/v1";

// 백엔드에 아직 없는 유저 목록/추천 블로그는 json-server 목업에서 받아온다.
const MOCK_BASE_URL =
  process.env.NEXT_PUBLIC_MOCK_API_BASE_URL ?? "http://localhost:4000";

async function fetchJSON<T>(url: string): Promise<T> {
  const res = await fetch(url, { cache: "no-store" });

  if (!res.ok) {
    throw new Error(`Failed to fetch ${url}`);
  }

  return res.json();
}

interface Paginated<T> {
  count: number;
  next: string | null;
  previous: string | null;
  results: T[];
}

interface RawCategory {
  id: number;
  name: string;
  slug: string;
  description: string;
  parent: number | null;
  order: number;
  post_count: number;
  children: RawCategory[];
}

interface RawTag {
  id: number;
  name: string;
  slug: string;
}

interface RawPost {
  id: number;
  slug: string;
  title: string;
  content?: string;
  summary: string;
  thumbnail: string | null;
  author: string;
  category: string | null;
  tags: RawTag[];
  status: Post["status"];
  view_count: number;
  like_count: number;
  comment_count: number;
  is_liked: boolean;
  created_at: string;
  updated_at?: string;
  published_at: string | null;
}

function mapCategory(raw: RawCategory): Category {
  return {
    id: raw.id,
    name: raw.name,
    slug: raw.slug,
    description: raw.description,
    parent: raw.parent,
    order: raw.order,
    postCount: raw.post_count,
    children: raw.children?.map(mapCategory) ?? [],
  };
}

function mapPost(raw: RawPost): Post {
  return {
    id: raw.id,
    slug: raw.slug,
    title: raw.title,
    summary: raw.summary,
    content: raw.content,
    thumbnail: raw.thumbnail,
    author: raw.author,
    category: raw.category,
    tags: raw.tags,
    status: raw.status,
    viewCount: raw.view_count,
    sympathyCount: raw.like_count,
    commentCount: raw.comment_count,
    isLiked: raw.is_liked,
    createdAt: raw.created_at,
    updatedAt: raw.updated_at,
    publishedAt: raw.published_at,
  };
}

export async function getCategories(): Promise<Category[]> {
  const raw = await fetchJSON<RawCategory[]>(`${API_BASE_URL}/categories/`);
  return raw.map(mapCategory);
}

export async function getTags(): Promise<Tag[]> {
  const data = await fetchJSON<Paginated<RawTag>>(`${API_BASE_URL}/tags/`);
  return data.results;
}

export function getUsers() {
  return fetchJSON<User[]>(`${MOCK_BASE_URL}/users`);
}

export function getRecommendedBlogs() {
  return fetchJSON<RecommendedBlog[]>(`${MOCK_BASE_URL}/recommendedBlogs`);
}

interface GetPostsParams {
  categorySlug?: string;
  tagSlug?: string;
  query?: string;
}

export async function getPosts(params: GetPostsParams = {}): Promise<Post[]> {
  const searchParams = new URLSearchParams();
  if (params.categorySlug) searchParams.set("category__slug", params.categorySlug);
  if (params.tagSlug) searchParams.set("tags__slug", params.tagSlug);

  const path = params.query
    ? `/posts/search/?q=${encodeURIComponent(params.query)}&${searchParams.toString()}`
    : `/posts/?${searchParams.toString()}`;

  const data = await fetchJSON<Paginated<RawPost>>(`${API_BASE_URL}${path}`);
  return data.results.map(mapPost);
}

export async function getPost(slug: string): Promise<Post> {
  const raw = await fetchJSON<RawPost>(`${API_BASE_URL}/posts/${slug}/`);
  return mapPost(raw);
}
